// The only per-kind part of the template: one row per notice kind.
const KINDS = {
  "maintenance": {
    "label": "점검",
    "prefix": "[점검 안내]",
    "max_length": 600,
    "required_phrases": [],
    "extra": "Say clearly what cannot be used during the work and what to do after it."
  },
  "security": {
    "label": "보안",
    "prefix": "[보안 안내]",
    "max_length": 500,
    "required_phrases": [
      "IT팀은 절대 비밀번호를 묻지 않습니다."
    ],
    "extra": "Tell readers what to do and what never to do. Never ask for passwords."
  },
  "training": {
    "label": "교육",
    "prefix": "[교육 안내]",
    "max_length": 800,
    "required_phrases": [
      "신청은 IT 포털에서 할 수 있습니다."
    ],
    "extra": "Say who should attend, when and where, and how to apply."
  }
};
const body = $('Kit webhook').first().json.body;
const kind = String(body.kind ?? '');
return [{ json: { known: true, kind, ...KINDS[kind] } }];

