// Rule checks. Same answer every time, so code, not the LLM.
const facts = String({ facts: $('Kit webhook').first().json.body.facts, draft: $json.draft, max_length: $('Kind settings').first().json.max_length, required_phrases: $('Kind settings').first().json.required_phrases }.facts ?? '');
const draft = String({ facts: $('Kit webhook').first().json.body.facts, draft: $json.draft, max_length: $('Kind settings').first().json.max_length, required_phrases: $('Kind settings').first().json.required_phrases }.draft ?? '');
const maxLength = Number({ facts: $('Kit webhook').first().json.body.facts, draft: $json.draft, max_length: $('Kind settings').first().json.max_length, required_phrases: $('Kind settings').first().json.required_phrases }.max_length ?? 600);
const required = Array.isArray({ facts: $('Kit webhook').first().json.body.facts, draft: $json.draft, max_length: $('Kind settings').first().json.max_length, required_phrases: $('Kind settings').first().json.required_phrases }.required_phrases) ? { facts: $('Kit webhook').first().json.body.facts, draft: $json.draft, max_length: $('Kind settings').first().json.max_length, required_phrases: $('Kind settings').first().json.required_phrases }.required_phrases : [];
const squeeze = text => text.replace(/\s+/g, '');
const tokens = [...new Set(facts.match(/\d{1,2}월\s?\d{1,2}일|\d{1,2}:\d{2}/g) ?? [])];
const issues = [];
const missing = tokens.filter(token => !squeeze(draft).includes(squeeze(token)));
if (missing.length) issues.push({ code: 'missing_fact', detail: missing.join(', ') });
const personal = draft.match(/01[016789]-?\d{3,4}-?\d{4}|[\w.+-]+@[\w-]+\.[\w.]+/g) ?? [];
if (personal.length) issues.push({ code: 'personal_info', detail: personal.join(', ') });
if (draft.length > maxLength) issues.push({ code: 'too_long', detail: `${draft.length}자 (${maxLength}자 이하)` });
const absent = required.filter(phrase => !squeeze(draft).includes(squeeze(String(phrase))));
if (absent.length) issues.push({ code: 'missing_phrase', detail: absent.join(' / ') });

return [{ json: { passed: issues.length === 0, codes: issues.map(issue => issue.code), issues } }];

// The kit's contract: { kind, route, published, notice, codes }.
const review = $json;
const draft = $('Build draft').first().json.draft;
return [{ json: { kind: $('Kind settings').first().json.kind, route: review.passed ? '게시 가능' : '담당자 확인',
  published: review.passed === true, notice: draft, codes: review.codes ?? [] } }];
